function durationFor(d,s,i){
 if(d.id===0)return '';
 if(s.id==='arima')return d.id===6?VISIT_TIMES.arima:'早餐、收拾与退房预留60–90分钟，按航班缩短';
 if(s.id==='kaigetsu')return d.id===6?VISIT_TIMES.kaigetsu:'早餐、收拾与退房预留60–90分钟，按送站时间倒排';
 if(s.id==='kameoka')return '候车预留15–20分钟；观光列车乘坐约25分钟';
 if(s.id==='wakakusa')return i===d.stops.findIndex(x=>x.id==='wakakusa')?'山麓入山准备约10–15分钟':'下山后短歇约10分钟';
 if(s.id==='sannomiya'&&d.id===6)return s.time.includes('12:00')?'午餐建议60分钟':'晚餐预留45–60分钟，19:30左右出发';
 if(HOTELS[s.id]&&s.id!=='arima'&&s.id!=='kaigetsu')return '';
 return VISIT_TIMES[s.id]||'';
}
