function budgetFor(d,p){return BUDGETS[p==='B'&&d.id>=6?`${d.id}B`:d.id];}
function sumBudget(b,includeHotel=true){return b.items.filter(x=>includeHotel||x.name!=='当晚住宿').reduce((a,x)=>[a[0]+x.min,a[1]+x.max],[0,0]);}
